<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowDownToLine, BookOpen, Code2, FileText, FolderOpen, LayoutGrid, Search, Sparkles, Trash2, X } from '@lucide/vue'
const router=useRouter();const search=ref('');const type=ref('全部');const preview=ref<typeof resources[number]|null>(null);const exportOpen=ref<number|null>(null)
const filters=['全部','文档','思维导图','代码','闪卡','项目','可视化'];const resources=[{id:1,type:'文档',title:'CNN 入门教程',desc:'从卷积层到经典架构的完整讲解',meta:'7月13日 · 12页',icon:FileText},{id:2,type:'思维导图',title:'CNN 知识结构',desc:'卷积、池化与全连接层的关系',meta:'7月13日',icon:BookOpen},{id:3,type:'代码',title:'PyTorch CNN 示例',desc:'一个可以直接运行的图像分类项目',meta:'7月12日 · Python',icon:Code2},{id:4,type:'闪卡',title:'CNN 核心概念',desc:'记忆卡片 · 共 12 张',meta:'7月11日',icon:LayoutGrid},{id:5,type:'项目',title:'手写数字识别',desc:'从数据处理到模型训练的完整实战',meta:'7月10日',icon:FolderOpen},{id:6,type:'可视化',title:'卷积过程可视化',desc:'用交互方式理解卷积核的移动过程',meta:'7月9日',icon:Sparkles}]
